TLM.f("Sancti/12-13r",{"officium":"S. Luciæ Virginis et Martyris","rule":["vide C6b;","Gloria"],"ruleInherited":["Prefatio=Virginis"],"fallback":"Commune/C6b","from":{"Tractus":"Commune/C6b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Exáudi nos, Deus salutáris noster: ut, sicut de beátae Lúciae Vírginis et Mártyris tuae festivitáte gaudémus; ita piae devotiónis erudiámur afféctu."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 10:17-18; 11:1-2"},{"k":"text","la":"Fratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo."}],"Graduale":[{"k":"ref","la":"Ps 44, 8"},{"k":"text","la":"Dilexísti iustítiam, et odísti iniquitátem. Proptérea unxit te Deus, Deus tuus, óleo laetítiae."},{"k":"sep"},{"k":"ref","la":"Ps 44, 3"},{"k":"text","la":"Allelúia, allelúia."},{"k":"text","la":"Difúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in aetérnum. Allelúia."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13; 44:10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Afferéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:161-162"},{"k":"text","la":"Príncipes persecúti sunt me gratis, et a verbis tuis formidávit cor meum: lætábor ego super elóquia tua, quasi qui invénit spólia multa."}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5f74a5115cb0ce83":{"t":"Ps 44, 8, Ps 44, 2\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje.","kn":"(Ps. 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti izabravši te od svih dru.garica tvojih, Aleluja, Aleluja (Ps. 44, 2). Iz mog srca Izvire divna pjesma: djela su moja namijenjena kralju! Slava Ocu. Ti ljubiš.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"0e40fdaf04d64ace":{"t":"<i>Pomolimo se</i>.\nUsliši nas, Bože Spasitelju naš, da kao što se radujemo svetkovini blažene Lucije djevice tvoje i mučenice, tako uznapredujemo u osjećaju odane pobožnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši nas. Bože, spasitelju naš, kao što se radujemo o blagdanu blažene Lucije, djevice i mučenice Tvoje, teko da nas ona pouči u pobožnoj bogoljubnosti, po G. n.","knRef":"Kniewald 1942, str. 456–457 (snimka 229) (OCR)"},"2e242204d5c46dd6":{"t":"2 Kor 10, 17-18, 11, 1-2\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, tko se hvali neka se hvali u Gospodinu. Jer nije prokušan onaj koji se sam hvali, nego koga Bog hvali. O da biste malo podnosili moje bezumlje! Ali ipak podnesite me, jer revnujem za vas Božjom revnošću. Zaručio sam vas jednom čovjeku Kristu da vas preda nj izvedem kao čistu djevicu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 10, 17-18. 11, 1-2). Braćo! Koji se hvali, neka se hvali u Gospodinu. Jer nije prokušan onaj, koji se sam preporučuje, nego koga preporučuje Bog. O da biste ipodnesld nešto malo moje ludosti! Ali ipak r po'dnesite me, jer revnujem za vas Božjim žarom. Zaručio sam vas jednomu mužu, da vas privedem Kristu kao čistu djevicu.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"be1e39e161f3c070":{"t":"Ps 44, 8\nLjubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti.\n\nPs 44, 3\n<i>Aleluja</i>, <i>aleluja</i>.\nRazlita je milina na usnama tvojim. Zbog toga te je Bog blagoslovio u vijeke. <i>Aleluja</i>.","kn":"(Ps, 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 44, 3). Milost se razlila usnama tvojim, zato te Bog blagoslovio zauvijek, aleluja.","knRef":"Kniewald 1942, str. 650–651 (snimka 326) (OCR)"},"599856a3c73c1a30":{"t":"Mt 13, 44-52\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi koje, kad čovjek nađe, sakrije, te veseo ode i proda sve što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac koji traži prave bisere. I kad nađe jedan dragocjeni biser, ode i proda sve što ima i kupi ga. Nadalje kraljevstvo je nebesko kao mreža koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude a izbace zle. Tako će biti na svršetku svijeta. Izići će anđeli i odijeliti će opake od pravednih i bacit će ih u ognjenu peć. Ondje će biti plač i škripanje zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik koji je poučen u tajnama kraljevstva nebeskoga kao domaćin koji od svoga blaga iznosi novo i staro.","kn":"t Slijedi sv. evanđelje po Matejn (13, 44-52). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao sakriveno blago u njivi, koje, kad čovjek nađe, sakrije, te veseo ode i proda sve, što ima i kupi onu njivu. Kraljevstvo je nebesko još kao trgovac, koji traži pravo biserje. I kad nađe jedan dragocjeni biser, ode i proda sve, što ima i kupi ga. Nadalje kraljevstvo^ je nebesko kao mreža, koja se baca u more i hvata sve vrsti riba. Kad se napuni, izvuku je i sjednu uz kraj, izaberu dobre ribe u posude, a izbace zle. Tako će biti na svršetku svijeta: Izići će anđeli i odijelit će opake od pravednih i bacit će ih u ognjenu peć; ondje će biti plač i škripa zubi. Jeste li razumjeli sve ovo? Odgovore mu: Jesmo. Tada im reče: Zato je svaki književnik,, koji je poučen u tajnaman kraljevstva nebeskoga, kao domaćin, koji od svoga blaga iznosi novo i staro.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"805e908c21018a9c":{"t":"Ps 44, 15-16\nZa njom će poći pred Kralja djevice. Drugarice će njezine poći k tebi u radosti, poći će u hram Kralja Gospodina.","kn":"(Ps. 44, 15, 16). Prate je djevice i vode je kralju; u radosti i veselju vode je u hram Kralja, Gosipodina.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"135c5bf58bce477d":{"t":"Neka ti bude, Gospodine, drag ovaj prinos što ga tvoj sveti narod prikazuje, u čast tvojih svetih priznavajući da je po njihovim zaslugama primio pomoć u nevolji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","c":"T01"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"6594159c5d6cf229":{"t":"Ps 118, 161-162\nPoglavice me progone ni za što, ali se srce moje boji samo riječi tvojih. Radujem se objavi tvojoj kao onaj koji je našao veliko blago.","kn":"(P,s. 118, 161, 162). Knezovi me progoniše ni za što, a je se bojim samo Tvojih riječi. Radujem se Tvojim riječima kao onaj, koji uhvati veliki plijen.","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
